     1→import Phaser from 'phaser';
     2→import { BattleChannel } from '../utils/battleChannel';
     3→import { BattleEvent, BattleResult } from '../types/BattleTypes';
     4→import { GameMode, Difficulty } from '../types/GameMode';
     5→import { POOP_CONFIG } from '../config/poop';
     6→import type Poop from '../objects/Poop';
     7→import GameScene from './GameScene';
     8→
     9→/** 생존 시간(ms)을 "12.3초" 또는 "1:05.0" 형식으로 변환 */
    10→function formatSurvivalTime(ms: number): string {
    11→  const totalSec = ms / 1000;
    12→  if (totalSec < 60) {
    13→    return `${totalSec.toFixed(1)}초`;
    14→  }
    15→  const min = Math.floor(totalSec / 60);
    16→  const sec = (totalSec % 60).toFixed(1).padStart(4, '0');
    17→  return `${min}:${sec}`;
    18→}
    19→
    20→interface BattleInitData {
    21→  gameMode?: string;
    22→  difficulty?: string;
    23→  purePhysical?: boolean;
    24→  roomCode?: string;
    25→  userId?: string;
    26→  opponentId?: string;
    27→  isRanked?: boolean;
    28→}
    29→
    30→/**
    31→ * 대전 게임 씬 — GameScene을 상속하여 코드 재사용
    32→ *
    33→ * BattleMatchScene에서 roomCode/userId를 받아 새 채널을 직접 생성합니다.
    34→ * (Supabase Realtime은 리스너 등록 → subscribe 순서 필수)
    35→ */
    36→export default class BattleGameScene extends GameScene {
    37→  private battleChannel: BattleChannel | null = null;
    38→  private roomCode: string = '';
    39→  private battleUserId: string = '';
    40→  private opponentId: string = '';
    41→  private isRanked: boolean = false;
    42→  private opponentScore: number = 0;
    43→  private opponentScoreText!: Phaser.GameObjects.Text;
    44→  private scoreUpdateTimer!: Phaser.Time.TimerEvent;
    45→  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
    46→  private battleFinished: boolean = false;
    47→  private survivalMs: number = 0;
    48→  private survivalTimerEvent!: Phaser.Time.TimerEvent;
    49→  private survivalText!: Phaser.GameObjects.Text;
    50→  private pendingPoopSends: number = 0; // 채널 준비 전 수집한 특수 똥 → 연결 후 전송
    51→
    52→  constructor() {
    53→    super('BattleGameScene');
    54→  }
    55→
    56→  // 배틀 모드는 EXTREME 기준보다 똥 1개 적게 생성 (난이도 조정)
    57→  protected override extraPoopCountReduction(): number { return 1; }
    58→
    59→  init(data: BattleInitData) {
    60→    this.roomCode = data.roomCode ?? '';
    61→    this.battleUserId = data.userId ?? '';
    62→    this.opponentId = data.opponentId ?? '';
    63→    this.isRanked = data.isRanked ?? false;
    64→    this.opponentScore = 0;
    65→    this.survivalMs = 0;
    66→    this.battleFinished = false;
    67→    this.channelReady = false;
    68→    this.pendingPoopSends = 0;
    69→
    70→    // 부모 init 호출: EXTREME 난이도 고정, BATTLE 모드
    71→    super.init({
    72→      gameMode: GameMode.BATTLE,
    73→      difficulty: Difficulty.EXTREME,
    74→      purePhysical: false,
    75→    });
    76→  }
    77→
    78→  create() {
    79→    super.create();
    80→
    81→    // 대전 모드에서는 점수 / 최고 기록 표시 불필요 → 생존 시간으로 대체
    82→    if (this.scoreText) this.scoreText.setVisible(false);
    83→    if (this.highScoreText) this.highScoreText.setVisible(false);
    84→
    85→    // 내 생존 시간 (좌상단)
    86→    this.survivalText = this.add.text(10, 3, '⏱ 0.0초', {
    87→      fontSize: '14px',
    88→      color: '#ffffff',
    89→      fontStyle: 'bold',
    90→      stroke: '#000000',
    91→      strokeThickness: 3,
    92→    }).setOrigin(0, 0).setDepth(10);
    93→
    94→    // 상대 생존 시간 (우상단)
    95→    this.opponentScoreText = this.add.text(390, 3, '상대: --', {
    96→      fontSize: '14px',
    97→      color: '#ff6666',
    98→      fontStyle: 'bold',
    99→      stroke: '#000000',
   100→      strokeThickness: 3,
   101→    }).setOrigin(1, 0).setDepth(10);
   102→
   103→    // 생존 타이머 (100ms 주기)
   104→    this.survivalTimerEvent = this.time.addEvent({
   105→      delay: 100,
   106→      callback: () => {
   107→        if (!this.gameOver) {
   108→          this.survivalMs += 100;
   109→          if (this.survivalText?.active) {
   110→            this.survivalText.setText(`⏱ ${formatSurvivalTime(this.survivalMs)}`);
   111→          }
   112→        }
   113→      },
   114→      loop: true,
   115→    });
   116→
   117→    // 연결 상태 표시
   118→    const connectingText = this.add.text(200, 55, '⏳ 상대와 연결 중...', {
   119→      fontSize: '13px',
   120→      color: '#ffaa00',
   121→      stroke: '#000',
   122→      strokeThickness: 3,
   123→    }).setOrigin(0.5).setDepth(10);
   124→
   125→    // 새 채널 생성 → 리스너 등록 → subscribe → 점수 타이머 시작
   126→    this.initBattleChannel(connectingText);
   127→  }
   128→
   129→  /** 채널 연결 완료 여부 (send 호출 가드) */
   130→  private channelReady: boolean = false;
   131→
   132→  /**
   133→   * 새 채널 생성 → 리스너 등록 → subscribe → 점수 타이머 시작
   134→   */
   135→  private async initBattleChannel(connectingText: Phaser.GameObjects.Text) {
   136→    this.battleChannel = new BattleChannel();
   137→    this.battleChannel.joinRoom(this.roomCode, this.battleUserId);
   138→
   139→    // 리스너 등록 (subscribe 전 — Supabase Realtime 필수 패턴)
   140→    this.setupBattleListeners();
   141→
   142→    // 구독 시작
   143→    await this.battleChannel.subscribe();
   144→    this.channelReady = true;
   145→
   146→    // 채널 준비 전 수집된 특수 똥 → 지금 전송
   147→    if (this.pendingPoopSends > 0 && !this.gameOver) {
   148→      this.battleChannel.sendPoop(this.pendingPoopSends);
   149→      this.pendingPoopSends = 0;
   150→    }
   151→
   152→    // 연결 완료 표시
   153→    if (connectingText?.active) {
   154→      connectingText.setText('✅ 연결 완료!');
   155→      connectingText.setColor('#00ff00');
   156→      this.time.delayedCall(1500, () => {
   157→        if (connectingText.active) connectingText.destroy();
   158→      });
   159→    }
   160→
   161→    // 구독 완료 후 점수 타이머 시작 (구독 전 전송 방지)
   162→    this.scoreUpdateTimer = this.time.addEvent({
   163→      delay: 1000,
   164→      callback: () => {
   165→        if (!this.gameOver && this.battleChannel && this.channelReady) {
   166→          this.battleChannel.sendScoreUpdate(this.survivalMs);
   167→        }
   168→      },
   169→      loop: true,
   170→    });
   171→  }
   172→
   173→  private setupBattleListeners() {
   174→    if (!this.battleChannel) return;
   175→
   176→    // 상대가 보낸 똥 수신
   177→    this.battleChannel.onEvent(BattleEvent.SEND_POOP, (payload) => {
   178→      if (!this.gameOver) {
   179→        this.onReceivePoop(payload.count);
   180→      }
   181→    });
   182→
   183→    // 상대 생존 시간 갱신
   184→    this.battleChannel.onEvent(BattleEvent.SCORE_UPDATE, (payload) => {
   185→      this.opponentScore = payload.score;
   186→      if (this.opponentScoreText?.active) {
   187→        this.opponentScoreText.setText(`상대: ${formatSurvivalTime(this.opponentScore)}`);
   188→      }
   189→    });
   190→
   191→    // 상대 사망 → 즉시 승리
   192→    this.battleChannel.onEvent(BattleEvent.GAME_OVER, (payload) => {
   193→      if (!this.battleFinished) {
   194→        this.opponentScore = payload.finalScore;
   195→        // 패배 측이 최종 생존 시간을 표시할 수 있도록 현재 값을 한 번 더 전송
   196→        if (this.channelReady && this.battleChannel) {
   197→          this.battleChannel.sendScoreUpdate(this.survivalMs);
   198→        }
   199→        this.endBattle(BattleResult.WIN);
   200→      }
   201→    });
   202→
   203→    // 상대 이탈 → 5초 대기 후 부전승
   204→    this.battleChannel.onPresenceLeave(() => {
   205→      if (!this.battleFinished && !this.gameOver) {
   206→        this.showDisconnectWarning();
   207→        this.disconnectTimer = setTimeout(() => {
   208→          if (!this.battleFinished) {
   209→            this.endBattle(BattleResult.DISCONNECT);
   210→          }
   211→        }, 5000);
   212→      }
   213→    });
   214→
   215→    // 상대 재접속 시 타이머 취소
   216→    this.battleChannel.onPresenceJoin(() => {
   217→      if (this.disconnectTimer) {
   218→        clearTimeout(this.disconnectTimer);
   219→        this.disconnectTimer = null;
   220→        this.hideDisconnectWarning();
   221→      }
   222→    });
   223→  }
   224→
   225→  /**
   226→   * 특수 똥 수집 시 — 부모 처리 후 상대에게 똥 전송
   227→   */
   228→  protected handleSpecialCollected(
   229→    poop: Phaser.Physics.Arcade.Sprite,
   230→    type: import('../abilities/types').SpecialPoopType,
   231→    baseScore: number,
   232→    emoji: string,
   233→    color: string,
   234→    counterIncrement: () => void,
   235→  ) {
   236→    super.handleSpecialCollected(poop, type, baseScore, emoji, color, counterIncrement);
   237→
   238→    // 상대에게 일반 똥 1개 전송 (채널 미준비 시 pending 큐에 저장 → 연결 후 플러시)
   239→    if (!this.gameOver) {
   240→      if (this.battleChannel && this.channelReady) {
   241→        this.battleChannel.sendPoop(1);
   242→      } else {
   243→        this.pendingPoopSends += 1;
   244→        return; // 채널 미준비 시 알림 생략
   245→      }
   246→
   247→      const sendText = this.add.text(200, 150, '💩→ 상대에게 전송!', {
   248→        fontSize: '16px',
   249→        color: '#ff4444',
   250→        fontStyle: 'bold',
   251→        stroke: '#000',
   252→        strokeThickness: 3,
   253→      }).setOrigin(0.5).setDepth(200);
   254→      this.tweens.add({
   255→        targets: sendText,
   256→        alpha: 0,
   257→        y: 120,
   258→        duration: 800,
   259→        onComplete: () => sendText.destroy(),
   260→      });
   261→    }
   262→  }
   263→
   264→  /**
   265→   * 피격 시 — 부모 처리 후 상대에게 사망 알림
