   302→  private async fetchMyRating() {
   303→    // 1) 캐시 즉시 반영
   304→    const cached = getCachedMyRating();
   305→    if (cached) {
   306→      this.cachedMyRp = cached.rp;
   307→      this.cachedMyRank = cached.rank;
   308→      this.updateRankBadge(cached.rp, cached.rank);
