   311→    // 2) API 호출 후 캐시 갱신 + UI 업데이트
   312→    try {
   313→      const stats = await getMyRating();
   314→      if (stats) {
   315→        this.cachedMyRp = stats.ratingPoints;
   316→        this.cachedMyRank = stats.rank;
   317→        setCachedMyRating(stats.ratingPoints, stats.rank);
   318→        this.updateRankBadge(stats.ratingPoints, stats.rank);
   319→      } else {
   320→        // 전적 없음: 캐시 삭제 + 배지 숨김
   321→        clearCachedMyRating();
   322→        this.cachedMyRp = null;
   323→        this.cachedMyRank = null;
   324→        this.rankBadgeImg?.setAlpha(0);
