   814→    this.battleChannel.onPresenceLeave(() => {
   815→      this.opponentReady = false;
   816→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
   817→        fontSize: '16px', color: '#ff4444',
