   860→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   861→      stroke: '#000', strokeThickness: 4,
   862→    }).setOrigin(0.5));
   863→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   864→      fontSize: '16px', color: '#ffffff',
   865→      stroke: '#000', strokeThickness: 3,
   866→    }).setOrigin(0.5));
   867→
   868→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   869→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   870→    this.clearReadyRetry();
