   901→
   902→    let count = 3;
   903→    const countText = this.ui(this.add.text(200, 280, `${count}`, {
   904→      fontSize: '90px', color: '#ff4444', fontStyle: 'bold',
   905→      stroke: '#000', strokeThickness: 8,
   906→    }).setOrigin(0.5));
   907→
   908→    const timer = this.time.addEvent({
   909→      delay: 1000,
