   914→        } else {
   915→          (countText as Phaser.GameObjects.Text).setText('GO!');
   916→          (countText as Phaser.GameObjects.Text).setColor('#00ff00');
   917→          timer.remove();
   918→          this.time.delayedCall(500, () => this.goToBattle());
