     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→const VALID_RESULTS = ['win', 'lose', 'disconnect'] as const;
     9→type BattleResultValue = typeof VALID_RESULTS[number];
    10→
    11→// ── 티어 계산 (battleTier.ts 로직 인라인 — Deno에서 로컬 TS 공유 불가) ──
    12→
    13→interface TierDef {
    14→  minRp: number;
    15→  maxRp: number;
    16→}
    17→
    18→const TIERS: TierDef[] = [
    19→  { minRp: 0,    maxRp: 499 },
    20→  { minRp: 500,  maxRp: 999 },
    21→  { minRp: 1000, maxRp: 1499 },
    22→  { minRp: 1500, maxRp: 1999 },
    23→  { minRp: 2000, maxRp: Infinity },
    24→];
    25→
    26→const TIER_NAMES = ['알파', '베타', '레거시', '마스터', '갓'];
    27→const TIER_ICONS = ['🔴', '🟠', '🟡', '💎', '👑'];
    28→
    29→function getTierIndex(rp: number): number {
    30→  for (let i = TIERS.length - 1; i >= 0; i--) {
    31→    if (rp >= TIERS[i].minRp) return i;
    32→  }
    33→  return 0;
    34→}
    35→
    36→function calcPointDelta(
    37→  result: BattleResultValue,
    38→  myRp: number,
    39→  opponentRp: number,
    40→): number {
    41→  if (result === 'disconnect') return 20;
    42→
    43→  const tierDiff = getTierIndex(opponentRp) - getTierIndex(myRp);
    44→
    45→  if (result === 'win') {
    46→    if (tierDiff >= 2)   return 35;
    47→    if (tierDiff === 1)  return 30;
    48→    if (tierDiff === 0)  return 25;
    49→    if (tierDiff === -1) return 20;
    50→    return 15;
    51→  } else {
    52→    if (tierDiff >= 2)   return -10;
    53→    if (tierDiff === 1)  return -15;
    54→    if (tierDiff === 0)  return -20;
    55→    if (tierDiff === -1) return -25;
    56→    return -30;
    57→  }
    58→}
    59→
    60→// ── 메인 핸들러 ──
    61→
    62→Deno.serve(async (req: Request) => {
    63→  if (req.method === 'OPTIONS') {
    64→    return new Response('ok', { headers: corsHeaders });
    65→  }
    66→
    67→  try {
    68→    const { result, opponentId, isRanked = true } = await req.json();
    69→
    70→    // 입력 검증
    71→    if (!VALID_RESULTS.includes(result)) {
    72→      return new Response(
    73→        JSON.stringify({ error: 'Invalid result: must be win, lose, or disconnect' }),
    74→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    75→      );
    76→    }
    77→
    78→    // JWT 인증 (필수)
    79→    const authHeader = req.headers.get('Authorization');
    80→    if (!authHeader) {
    81→      return new Response(
    82→        JSON.stringify({ error: 'Missing authorization header' }),
    83→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    84→      );
    85→    }
    86→
    87→    const supabaseUser = createClient(
    88→      Deno.env.get('SUPABASE_URL') ?? '',
    89→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    90→      { global: { headers: { Authorization: authHeader } } },
    91→    );
    92→
    93→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    94→    if (authError || !user) {
    95→      return new Response(
    96→        JSON.stringify({ error: 'Unauthorized' }),
    97→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    98→      );
    99→    }
   100→
   101→    const supabaseAdmin = createClient(
   102→      Deno.env.get('SUPABASE_URL') ?? '',
   103→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
   104→    );
   105→
   106→    // 내 RP + 상대 RP 병렬 조회 (maybeSingle: 행 없으면 에러 없이 null 반환)
   107→    const hasOpponent = opponentId && typeof opponentId === 'string';
   108→    const [myResp, oppResp] = await Promise.all([
   109→      supabaseAdmin
   110→        .from('battle_records')
   111→        .select('rating_points')
   112→        .eq('user_id', user.id)
   113→        .maybeSingle(),
   114→      hasOpponent
   115→        ? supabaseAdmin
   116→            .from('battle_records')
   117→            .select('rating_points')
   118→            .eq('user_id', opponentId)
   119→            .maybeSingle()
   120→        : Promise.resolve({ data: null }),
   121→    ]);
   122→
   123→    const myRp: number = (myResp.data as { rating_points: number } | null)?.rating_points ?? 0;
   124→    const opponentRp: number = (oppResp.data as { rating_points: number } | null)?.rating_points ?? 0;
   125→
   126→    // RP 변동 계산 (친선전은 0 고정)
   127→    const pointDelta = isRanked
   128→      ? calcPointDelta(result as BattleResultValue, myRp, opponentRp)
   129→      : 0;
   130→
   131→    // 원자적 upsert + 전적 갱신 (DB 함수)
   132→    const { data: records, error: rpcError } = await supabaseAdmin.rpc(
   133→      'submit_battle_record',
   134→      { p_user_id: user.id, p_result: result, p_point_delta: pointDelta, p_is_ranked: isRanked },
   135→    );
   136→
   137→    if (rpcError || !records || records.length === 0) {
   138→      console.error('RPC error detail:', JSON.stringify(rpcError));
   139→      console.error('records:', JSON.stringify(records));
   140→      return new Response(
   141→        JSON.stringify({
   142→          error: 'Failed to update battle record',
   143→          detail: rpcError?.message ?? 'no records returned',
   144→          code: rpcError?.code,
   145→        }),
   146→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   147→      );
   148→    }
   149→
   150→    const record = records[0];
   151→    const newRp: number = record.out_rating_points;
   152→    const totalRankedGames = record.out_wins + record.out_losses + record.out_disconnects;
   153→    const winRate = totalRankedGames === 0
   154→      ? 0
   155→      : Math.round((record.out_wins + record.out_disconnects) / totalRankedGames * 1000) / 10;
   156→
   157→    const tierIdx = getTierIndex(newRp);
   158→
   159→    return new Response(
   160→      JSON.stringify({
   161→        success: true,
   162→        previousRp: myRp,
   163→        ratingPoints: newRp,
   164→        pointDelta,
   165→        wins: record.out_wins,
   166→        losses: record.out_losses,
   167→        disconnects: record.out_disconnects,
   168→        friendlyWins: record.out_friendly_wins,
   169→        friendlyLosses: record.out_friendly_losses,
   170→        friendlyDisconnects: record.out_friendly_disconnects,
   171→        winRate,
   172→        rank: Number(record.out_rank),
   173→        tierName: TIER_NAMES[tierIdx],
   174→        tierIcon: TIER_ICONS[tierIdx],
   175→      }),
   176→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   177→    );
   178→  } catch (error) {
   179→    console.error('Unexpected error:', error);
   180→    return new Response(
   181→      JSON.stringify({ error: 'Internal server error' }),
   182→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   183→    );
   184→  }
   185→});
