    51→const _CACHE_KEY     = 'battleRatingCache';
    52→const _CACHE_SIG_KEY = 'battleRatingCacheSig';
    53→const _CACHE_SALT    = 'ddong-battle-rating-\u0076\u0031';
    54→
    55→interface RatingCache { rp: number; rank: number | null; }
    56→
    57→function _signCache(c: RatingCache): string {
    58→  const str = `rp:${c.rp},rank:${c.rank ?? 'null'}` + _CACHE_SALT;
    59→  let h = 5381;
    60→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
    61→  return h.toString(36);
    62→}
