    66→  try {
    67→    const raw = localStorage.getItem(_CACHE_KEY);
    68→    const sig = localStorage.getItem(_CACHE_SIG_KEY);
    69→    if (!raw || !sig) return null;
    70→    const cache = JSON.parse(raw) as RatingCache;
    71→    if (sig !== _signCache(cache)) return null;
    72→    return cache;
    73→  } catch {
    74→    return null;
    75→  }
    76→}
