   184→    this.battleChannel.onEvent(BattleEvent.SCORE_UPDATE, (payload) => {
   185→      this.opponentScore = payload.score;
   186→      if (this.opponentScoreText?.active) {
   187→        this.opponentScoreText.setText(`상대: ${formatSurvivalTime(this.opponentScore)}`);
   188→      }
   189→    });
   190→
   191→    // 상대 사망 → 즉시 승리
