   211→        }, 5000);
   212→      }
   213→    });
   214→
   215→    // 상대 재접속 시 타이머 취소
   216→    this.battleChannel.onPresenceJoin(() => {
   217→      if (this.disconnectTimer) {
   218→        clearTimeout(this.disconnectTimer);
